var i=`prompt-engineering`;var n=113;var o={en:[{id:`T113-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Prompt Engineering`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Specification-driven development starts with an explicit, testable description of required behavior before implementation.`},{id:`B`,text:`Context engineering curates the information, tools and constraints available to an AI model for a task.`},{id:`C`,text:`Prompt injection occurs when untrusted content tries to redirect an AI system's instructions or tool use.`},{id:`D`,text:`Prompt engineering structures instructions and examples to make model output more relevant, constrained and verifiable.`}]},{id:`T113-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Prompt Engineering`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Provide a clear task, inputs, constraints, output format and acceptance checks.`},{id:`B`,text:`Treat external text as data, enforce instruction hierarchy in the agent runtime, sandbox tools, restrict file/network permissions and protect secrets.`},{id:`C`,text:`Break tasks into inspect-plan-implement-test-review stages, grant only required tool capabilities, and persist decisions in version control.`},{id:`D`,text:`Supply only relevant files, current API contracts, examples, acceptance criteria and forbidden changes.`}]},{id:`T113-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`Prompt Engineering`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Instead of 'build an admin page,' specify route, permissions, data fields, loading states, error UX, component conventions, tests and files the agent may modify.`},{id:`B`,text:`A malicious README may tell a coding agent to read environment secrets and upload them while 'fixing tests.' Repository content must never authorize secret exfiltration or unrelated shell commands.`},{id:`C`,text:`Before adding a booking endpoint, an agent receives the module map, repository conventions, current data model, auth policy and one existing endpoint as a reference, not the entire monorepo dump.`},{id:`D`,text:`A coding agent can update unit tests freely in a branch but should require approval before running a migration that changes production booking records.`}]},{id:`T113-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Prompt Engineering`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`AI often writes tests that assert the current implementation instead of the intended behavior.`},{id:`B`,text:`Unbounded autonomy can produce unrelated edits, fabricated tests or leaked secrets.`},{id:`C`,text:`A long prompt full of conflicting instructions is worse than a concise authoritative spec.`},{id:`D`,text:`Benchmark contamination, flaky tests and cherry-picked tasks mislead results.`}]},{id:`T113-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`For coding, a good prompt states goals, context, boundaries and evidence requirements rather than just desired code volume.`}]}]},{id:`T113-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`A confident AI response is proof that its code passed all required checks.`}]}]},{id:`T113-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Avoid relying on persona tricks, false confidence, or instructions to skip verification.`}]}]},{id:`T113-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Prompt Engineering`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Prompt length and persona tricks are more important than acceptance tests.`},{id:`B`,text:`Provide a clear task, inputs, constraints, output format and acceptance checks.`},{id:`C`,text:`More repository context always improves an agent's results, even when it is stale.`},{id:`D`,text:`Prompt engineering structures instructions and examples to make model output more relevant, constrained and verifiable.`}]},{id:`T113-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Prompt Engineering`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Instead of 'build an admin page,' specify route, permissions, data fields, loading states, error UX, component conventions, tests and files the agent may modify.`},{id:`B`,text:`Sandboxing cannot reduce the impact of a malicious instruction in tool output.`},{id:`C`,text:`Avoid relying on persona tricks, false confidence, or instructions to skip verification.`},{id:`D`,text:`A confident AI response is proof that its code passed all required checks.`}]},{id:`T113-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`Instead of 'build an admin page,' specify route, permissions, data fields, loading states, error UX, component conventions, tests and files the agent may modify.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to design an internal benchmark harness with fixed tasks, independent acceptance tests, safety checks, cost tracking and versioned result reports.`},{id:`B`,text:`Ask an agent to derive reservation tests solely from a written policy, then compare them with implementation and flag mismatches instead of adjusting expectations to pass.`},{id:`C`,text:`Ask an agent to plan a two-module feature as scoped tasks, specifying tool permissions, checkpoints, approval gates and evidence required at handoff.`},{id:`D`,text:`Ask an agent to rewrite a vague frontend task as a structured implementation brief with acceptance criteria and a review checklist, then compare the resulting diffs.`}]},{id:`T113-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Which critical constraints are implicit in your current prompt and therefore easy for AI to miss?`}]}]},{id:`T113-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`Instead of 'build an admin page,' specify route, permissions, data fields, loading states, error UX, component conventions, tests and files the agent may modify.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Prompt Engineering`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T113-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`Instead of 'build an admin page,' specify route, permissions, data fields, loading states, error UX, component conventions, tests and files the agent may modify.`,b:!0},{t:` — propose three checks for `},{t:`Prompt Engineering`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T113-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`Instead of 'build an admin page,' specify route, permissions, data fields, loading states, error UX, component conventions, tests and files the agent may modify.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T113-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Prompt Engineering`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`Instead of 'build an admin page,' specify route, permissions, data fields, loading states, error UX, component conventions, tests and files the agent may modify.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T113-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Інженерія промптів`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Розробка на основі специфікацій починається з чіткого, перевірюваного опису поведінки до реалізації.`},{id:`B`,text:`Інженерія контексту керує інформацією, інструментами та обмеженнями, доступними ШІ для задачі.`},{id:`C`,text:`Prompt injection виникає, коли недовірений контент намагається змінити інструкції ШІ чи його використання інструментів.`},{id:`D`,text:`Інженерія промптів структурує інструкції та приклади для релевантного, обмеженого й перевірюваного результату ШІ.`}]},{id:`T113-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Інженерія промптів`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Задайте чітку задачу, входи, обмеження, формат і критерії приймання.`},{id:`B`,text:`Сприймайте зовнішній текст як дані, забезпечуйте ієрархію інструкцій у runtime агента, ізолюйте інструменти, обмежуйте файли/мережу й захищайте секрети.`},{id:`C`,text:`Діліть роботу на inspect-plan-implement-test-review, надавайте лише потрібні інструменти та фіксуйте рішення в Git.`},{id:`D`,text:`Надавайте релевантні файли, чинні API-контракти, приклади, критерії приймання й заборонені зміни.`}]},{id:`T113-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Інженерія промптів`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Замість «зроби адмінку» задайте route, права, поля, loading-стани, UX помилок, конвенції компонентів, тести та дозволені файли.`},{id:`B`,text:`Шкідливий README може наказати агенту прочитати секрети середовища й кудись надіслати їх під виглядом «виправлення тестів». Текст репозиторію не має права дозволяти витік секретів чи сторонні команди.`},{id:`C`,text:`Перед додаванням booking endpoint агент отримує карту модулів, конвенції, модель даних, політику доступу й один наявний endpoint як приклад, а не весь монорепозиторій.`},{id:`D`,text:`Агент може вільно оновлювати unit-тести в гілці, але має отримати дозвіл перед міграцією production-записів бронювання.`}]},{id:`T113-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Інженерія промптів`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`ШІ часто пише тести під поточну реалізацію, а не під задуману поведінку.`},{id:`B`,text:`Необмежена автономія створює сторонні зміни, вигадані результати тестів або витік секретів.`},{id:`C`,text:`Довгий промпт із суперечливими вимогами гірший за лаконічну специфікацію.`},{id:`D`,text:`Засмічені бенчмарки, нестабільні тести й вибір зручних задач спотворюють результати.`}]},{id:`T113-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Для коду хороший промпт формулює мету, контекст, межі й докази, а не бажану кількість рядків.`}]}]},{id:`T113-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Впевнена відповідь ШІ доводить, що його код пройшов усі перевірки.`}]}]},{id:`T113-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Не покладайтеся на рольові трюки, удавану впевненість чи прохання пропустити перевірку.`}]}]},{id:`T113-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Інженерія промптів`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Довжина промпту й рольові трюки важливіші за критерії приймання.`},{id:`B`,text:`Задайте чітку задачу, входи, обмеження, формат і критерії приймання.`},{id:`C`,text:`Більше контексту репозиторію завжди покращує відповіді агента, навіть якщо він застарілий.`},{id:`D`,text:`Інженерія промптів структурує інструкції та приклади для релевантного, обмеженого й перевірюваного результату ШІ.`}]},{id:`T113-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Інженерія промптів`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Замість «зроби адмінку» задайте route, права, поля, loading-стани, UX помилок, конвенції компонентів, тести та дозволені файли.`},{id:`B`,text:`Пісочниця не може зменшити шкоду від шкідливої інструкції у виводі інструмента.`},{id:`C`,text:`Не покладайтеся на рольові трюки, удавану впевненість чи прохання пропустити перевірку.`},{id:`D`,text:`Впевнена відповідь ШІ доводить, що його код пройшов усі перевірки.`}]},{id:`T113-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Замість «зроби адмінку» задайте route, права, поля, loading-стани, UX помилок, конвенції компонентів, тести та дозволені файли.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента описати внутрішній benchmark harness із фіксованими задачами, незалежними тестами, safety-перевірками, обліком вартості та версіонованими звітами.`},{id:`B`,text:`Попросіть агента вивести тести бронювання лише з письмової політики, потім зіставити їх із реалізацією та позначити розбіжності, а не підлаштовувати очікування.`},{id:`C`,text:`Попросіть агента розбити фічу на задачі двох модулів із дозволеними інструментами, контрольними точками, затвердженням і доказами готовності.`},{id:`D`,text:`Попросіть агента перетворити нечітку frontend-задачу на структурований brief з критеріями приймання й checklist review, після чого порівняйте diff.`}]},{id:`T113-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Які критичні обмеження залишилися неявними в промпті й тому легко пропускаються ШІ?`}]}]},{id:`T113-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Замість «зроби адмінку» задайте route, права, поля, loading-стани, UX помилок, конвенції компонентів, тести та дозволені файли.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Інженерія промптів`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T113-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Замість «зроби адмінку» задайте route, права, поля, loading-стани, UX помилок, конвенції компонентів, тести та дозволені файли.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Інженерія промптів`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T113-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Замість «зроби адмінку» задайте route, права, поля, loading-стани, UX помилок, конвенції компонентів, тести та дозволені файли.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T113-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Інженерія промптів`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Замість «зроби адмінку» задайте route, права, поля, loading-стани, UX помилок, конвенції компонентів, тести та дозволені файли.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var s={slug:i,topicId:113,questions:o};export{s as default,o as questions,i as slug,n as topicId};